import { chromium } from 'playwright-core';
import assert from 'node:assert/strict';
import { mkdir } from 'node:fs/promises';
const browser = await chromium.launch({ executablePath: process.env.CHROME_PATH ?? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
try {
 await mkdir('/tmp/malink-next-step-qa', {recursive:true});
 for (const width of [390,1280]) {
  const page = await browser.newPage({viewport:{width,height:844}});
  await page.emulateMedia({reducedMotion:'reduce'});
  const errors=[];
  page.on('pageerror', e=>errors.push(e.message));
  await page.goto(process.env.SETTINGS_FIXTURE_URL ?? 'http://127.0.0.1:4179/malink/tests/fixtures/computer-settings/');
  await page.getByRole('button',{name:'Manage Tokyo server · Tokyo',exact:true}).click();
  const status=()=>page.getByRole('status',{name:'Computer status'});
  const panel=()=>page.locator('.computer-action-dialog').last();
  const snap=async name=>{
   await page.screenshot({path:`/tmp/malink-next-step-qa/${name}-${width}.png`});
   assert.deepEqual(await page.evaluate(()=>[...document.querySelectorAll('.computer-action-body,.computer-details,.matrix-settings-body')].filter(el=>el.scrollWidth>el.clientWidth+2).map(el=>el.className)),[]);
  };
  assert.equal(await page.getByRole('button',{name:/^Versions/}).count(),0);
  assert.equal(await page.getByRole('button',{name:/^Rename/}).count(),0);
  await status().getByRole('button',{name:'Update',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.updatedNode),'tokyo');
  assert.equal(await status().getByRole('button',{name:'Refresh status',exact:true}).count(),1);
  await snap('preparing');
  await page.getByRole('button',{name:'All computers'}).click();
  await page.getByRole('button',{name:'Manage Mac mini · Office',exact:true}).click();
  await status().getByRole('button',{name:'Update',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.updatedNode),'mac');
  await page.getByRole('button',{name:'All computers'}).click();
  await page.getByRole('button',{name:'Manage Tokyo server · Tokyo',exact:true}).click();
  const checks=await page.evaluate(()=>window.checks);
  await page.getByRole('button',{name:/^Manage computer/}).click();
  assert.equal(await page.evaluate(()=>window.checks),checks);
  await panel().getByRole('button',{name:/^Update activity/}).click();
  await panel().getByRole('button',{name:'View update session',exact:true}).click();
  await page.getByRole('heading',{name:'Update session'}).waitFor();
  await page.getByRole('button',{name:'Back to computer settings'}).click();
  await page.evaluate(()=>window.setFixturePhase('committed'));
  await snap('healthy');
  assert.equal(await status().getByRole('button',{name:'Refresh status',exact:true}).count(),1);
  await page.getByRole('button',{name:/^Manage computer/}).click();
  await panel().getByRole('button',{name:/^Versions Installed/}).click();
  await panel().getByRole('button',{name:/Use previous version v1/}).click();
  assert.equal(await page.evaluate(()=>window.selectedVersion),undefined);
  await panel().getByRole('button',{name:'Confirm switch',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.selectedVersion),'v1');
  await page.keyboard.press('Escape');
  await panel().getByRole('button',{name:/^Rename Tokyo/}).click();
  await panel().getByRole('textbox',{name:'Computer name'}).fill('Home computer');
  await panel().getByRole('button',{name:'Save',exact:true}).click();
  await panel().getByRole('button',{name:/^Restart Gateway/}).click();
  assert.equal(await page.evaluate(()=>window.restart),undefined);
  await panel().getByRole('button',{name:'Restart when idle',exact:true}).click();
  assert.deepEqual(await page.evaluate(()=>window.restart),{id:'tokyo',project:'project',mode:'when_idle'});
  await page.keyboard.press('Escape');
  await page.keyboard.press('Escape');
  await page.evaluate(()=>window.setFixtureOldFailure());
  await status().getByText('Current state not confirmed',{exact:true}).waitFor();
  assert.equal(await status().getByRole('button').count(),1);
  await snap('old-failure');
  await status().getByRole('button',{name:'Refresh status',exact:true}).click();
  await snap('checking');
  await page.evaluate(()=>window.finishCheck(false));
  await status().getByText('No reply from this computer',{exact:true}).waitFor();
  assert.equal(await status().getByRole('button',{name:'Confirm current state',exact:true}).count(),0);
  await snap('no-reply');
  await status().getByRole('button',{name:'How to reconnect',exact:true}).click();
  await snap('reconnect');
  await panel().getByRole('button',{name:'Export report for support',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.exported),true);
  await panel().getByRole('button',{name:"I've done this — check connection",exact:true}).click();
  await page.evaluate(()=>window.finishCheck(true));
  await page.keyboard.press('Escape');
  await status().getByRole('button',{name:'Restore previous version…',exact:true}).waitFor();
  await snap('confirmed-repair');
  await status().getByRole('button',{name:'Restore previous version…',exact:true}).click();
  assert.equal(await panel().getByRole('button',{name:'Confirm switch',exact:true}).count(),1);
  await panel().getByRole('button',{name:'Confirm switch',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.selectedVersion),'v2');
  assert.equal(await status().getByRole('button',{name:'Refresh status',exact:true}).count(),1);
  await snap('restored');
  const beforeRefresh = await page.evaluate(()=>window.checks);
  await status().getByRole('button',{name:'Refresh status',exact:true}).click();
  assert.equal(await page.evaluate(()=>window.checks),beforeRefresh+1);
  await page.evaluate(()=>window.setFixtureForwardFailure());
  assert.equal(await status().getByRole('button',{name:'Restore previous version…',exact:true}).count(),0);
  await page.getByRole('button',{name:/^Manage computer/}).click();
  await panel().getByRole('button',{name:/^Versions/}).click();
  assert.equal(await panel().getByRole('button',{name:/Use previous version|Keep current version/}).count(),0);
  await panel().getByRole('button',{name:/Retry prepared update v3/}).waitFor();
  await snap('forward-only');
  assert.deepEqual(errors,[]);
  console.log(JSON.stringify({width,errors,confirmedRepair:true,noDuplicateManagementCheck:true}));
  await page.close();
 }
} finally { await browser.close(); }
